#include <bits/stdc++.h>
#include <omp.h>
using namespace std; static const int N=25; using A=array<int,N>; using Vec=array<int16_t,N>;
vector<int> units(){vector<int>u;for(int a=1;a<N;a++)if(gcd(a,N)==1)u.push_back(a);return u;}
uint32_t affmask(uint32_t x,int a,int b){uint32_t y=0;for(int i=0;i<N;i++)if(x>>i&1)y|=1u<<((a*i+b)%N);return y;}
struct Key{uint32_t as,gs;bool operator<(Key const&o)const{return as!=o.as?as<o.as:gs<o.gs;}};
vector<int> cmults(int lag){vector<int> v;if(lag==0){for(int a=1;a<N;a++)if(gcd(a,N)==1)v.push_back(a);}else if(lag==1)v={1,24};else if(lag==5){for(int a=1;a<N;a++)if(gcd(a,N)==1&&((a*5)%N==5||(a*5)%N==20))v.push_back(a);}else abort();return v;}
Key canon(uint32_t as,uint32_t gs,int lag){auto us=cmults(lag);Key z{UINT32_MAX,UINT32_MAX};for(int a:us)for(int b=0;b<N;b++){Key q{affmask(as,a,b),affmask(gs,a,b)};if(q<z)z=q;}return z;}
Vec comm_mask(uint32_t os,uint32_t op,int j){Vec f{};auto add=[&](int e,int v){if(e>=0)f[e]+=v;else f[e+N]-=v;};for(int i=0;i<N;i++)if(os>>i&1){int oi=(op>>i&1)?1:-1;add(i-j,oi);add(j-i,-oi);}return f;}
Vec comm(const A&a,const A&g){Vec f{};auto add=[&](int e,int v){if(e>=0)f[e]+=v;else f[e+N]-=v;};for(int i=0;i<N;i++)if(a[i])for(int j=0;j<N;j++)if(g[j]){add(i-j,a[i]*g[j]);add(j-i,-g[j]*a[i]);}return f;}
vector<uint32_t> solve_second(uint32_t os,uint32_t op,uint32_t ss,int lag,int orient){vector<int>sp;for(int i=0;i<N;i++)if(ss>>i&1)sp.push_back(i);int nc=sp.size();vector<vector<uint8_t>>a(25,vector<uint8_t>(nc));for(int j=0;j<nc;j++){auto v=comm_mask(os,op,sp[j]);for(int r=0;r<N;r++){int z=v[r]%3;if(z<0)z+=3;a[r][j]=z;}}int rhs[25]{};if(lag){rhs[lag]=orient>0?1:2;rhs[N-lag]=orient>0?1:2;}int rr=0;vector<int>piv;for(int c=0;c<nc&&rr<N;c++){int q=-1;for(int r=rr;r<N;r++)if(a[r][c]){q=r;break;}if(q<0)continue;swap(a[rr],a[q]);swap(rhs[rr],rhs[q]);if(a[rr][c]==2){for(int j=0;j<nc;j++)a[rr][j]=(2*a[rr][j])%3;rhs[rr]=(2*rhs[rr])%3;}for(int r=0;r<N;r++)if(r!=rr&&a[r][c]){int f=a[r][c];for(int j=0;j<nc;j++)a[r][j]=(a[r][j]+6-f*a[rr][j])%3;rhs[r]=(rhs[r]+6-f*rhs[rr])%3;}piv.push_back(c);rr++;}for(int r=rr;r<N;r++)if(rhs[r])return{};vector<char>isp(nc);for(int c:piv)isp[c]=1;vector<int>fr;for(int c=0;c<nc;c++)if(!isp[c])fr.push_back(c);uint64_t M=1ull<<fr.size();vector<uint32_t>out;vector<int>x(nc);A outer{};for(int i=0;i<N;i++)if(os>>i&1)outer[i]=(op>>i&1)?1:-1;
 for(uint64_t m=0;m<M;m++){fill(x.begin(),x.end(),0);for(int k=0;k<(int)fr.size();k++)x[fr[k]]=(m>>k&1)?2:1;bool ok=true;for(int r=rr-1;r>=0;r--){int z=rhs[r];for(int f:fr)z=(z-a[r][f]*x[f])%3;if(z<0)z+=3;if(z!=1&&z!=2){ok=false;break;}x[piv[r]]=z;}if(!ok)continue;A sec{};uint32_t plus=0;for(int j=0;j<nc;j++){int sg=x[j]==1?1:-1;sec[sp[j]]=sg;if(sg==1)plus|=1u<<sp[j];}auto v=comm(outer,sec);bool ex=true;for(int r=0;r<N;r++){int want=(lag&&(r==lag||r==N-lag))?orient:0;if(v[r]!=want){ex=false;break;}}if(ex)out.push_back(plus);}
 return out;}
int npaf(uint32_t supp,uint32_t plus,int r){uint32_t pair=supp&(supp>>r),sx=plus^(plus>>r);int non=__builtin_popcount(pair)-2*__builtin_popcount(pair&sx);uint32_t mr=(1u<<r)-1,hi=supp>>(N-r),lo=supp&mr,pw=hi&lo,sh=plus>>(N-r),sl=plus&mr;int wrap=__builtin_popcount(pw)-2*__builtin_popcount(pw&(sh^sl));return non-wrap;}
int sg(const A&p,const A&c){int s=0;for(int r=1;r<=12;r++){int g=0;for(int i=0;i<N;i++)g+=p[i]*p[(i+r)%N]+c[i]*c[(i+r)%N];s+=g*g;}return s;}
struct G{Key k;int minSG=999,count=0;};
int main(int argc,char**argv){if(argc<4)return 2;int budget=atoi(argv[3]);int lag=atoi(argv[1]);if(lag!=0&&lag!=1&&lag!=5)return 2;ifstream f(argv[2]);string line;map<Key,G>mp;long long hits=0;while(getline(f,line)){if(line.rfind("HIT ",0))continue;auto a=line.find("p="),b=line.find("|c=");if(a==string::npos||b==string::npos)continue;a+=2;string ps=line.substr(a,b-a),cs=line.substr(b+3);replace(ps.begin(),ps.end(),',',' ');replace(cs.begin(),cs.end(),',',' ');stringstream sp(ps),sc(cs);A p{},c{};uint32_t as=0,gs=0;for(int i=0;i<N;i++){sp>>p[i];if(!p[i])as|=1u<<i;}for(int i=0;i<N;i++){sc>>c[i];if(!c[i])gs|=1u<<i;}Key k=canon(as,gs,lag);auto &g=mp[k];g.k=k;g.count++;g.minSG=min(g.minSG,sg(p,c));hits++;}
 vector<G> groups;for(auto &kv:mp)groups.push_back(kv.second);cout<<"INPUT hits="<<hits<<" groups="<<groups.size()<<"\n";atomic<long long>half{0},qpass{0},outer{0};atomic<int>minmargin{999},minsh{999};
#pragma omp parallel for schedule(dynamic,1)
 for(int gi=0;gi<(int)groups.size();gi++){auto G0=groups[gi];int za=__builtin_popcount(G0.k.as),zg=__builtin_popcount(G0.k.gs);bool sw=zg<za;uint32_t os=sw?G0.k.gs:G0.k.as,ss=sw?G0.k.as:G0.k.gs;vector<int>opos;for(int i=0;i<N;i++)if(os>>i&1)opos.push_back(i);uint64_t OM=1ull<<(opos.size()-1);long long lh=0,lq=0;int lm=999;
  for(uint64_t m=0;m<OM;m++){uint32_t op=1u<<opos[0];for(int t=1;t<(int)opos.size();t++)if(m>>(t-1)&1)op|=1u<<opos[t];outer++;vector<int> orientations=lag?vector<int>{1,-1}:vector<int>{0};for(int finalOrient:orientations){int solveOrient=sw?-finalOrient:finalOrient;auto sols=solve_second(os,op,ss,lag,solveOrient);lh+=sols.size();for(auto spm:sols){uint32_t ap=sw?spm:op,gp=sw?op:spm;int sh=0;for(int r=1;r<=12;r++){int h=npaf(G0.k.as,ap,r)+npaf(G0.k.gs,gp,r);sh+=h*h;}lm=min(lm,sh);if(G0.minSG+sh<=budget){lq++;
#pragma omp critical
    cout<<"QHIT lag="<<lag<<" orient="<<finalOrient<<" as="<<G0.k.as<<" gs="<<G0.k.gs<<" minSG="<<G0.minSG<<" sh="<<sh<<" amask="<<ap<<" gmask="<<gp<<"\n";}}}}
  half+=lh;qpass+=lq;if(lm<999){int old=minsh.load();while(lm<old&&!minsh.compare_exchange_weak(old,lm)){}int mar=G0.minSG+lm-budget;old=minmargin.load();while(mar<old&&!minmargin.compare_exchange_weak(old,mar)){}}
 }
 cout<<"SUMMARY budget="<<budget<<" groups="<<groups.size()<<" outer="<<outer<<" half="<<half<<" qpass="<<qpass<<" minSH="<<minsh<<" minmargin="<<minmargin<<"\n";
}
